**ملاحظة:** يجب أن يكون المستخدم قد منح الإذن للوصول إلى الكاميرا مسبقًا لكي يعمل هذا السكربت.

```javascript
// التحقق من أذونات كاميرا الويب

async function checkWebcamPermissions() {
    try {
        // طلب الوصول إلى كاميرا الويب
        const stream = await navigator.mediaDevices.getUserMedia({ video: true });

        // إذا تم منح الإذن بنجاح، قم بإغلاق تدفق الفيديو (اختياري، لكن مفيد للاختبار)
        stream.getTracks().forEach(track => track.stop());

        console.log("تم منح إذن الوصول إلى كاميرا الويب بنجاح.");
        // هنا يمكنك إضافة المزيد من التعليمات البرمجية لمعالجة تدفق الفيديو أو عرض الفيديو في عنصر HTML.

    } catch (error) {
        console.error("فشل الوصول إلى كاميرا الويب:", error);

        // فحص رسالة الخطأ لتحديد سبب الرفض
        if (error.name === 'NotAllowedError') {
            console.log("تم رفض الوصول إلى كاميرا الويب. يرجى منح الإذن في إعدادات المتصفح.");
        } else if (error.name === 'PermissionDeniedError') {
            console.log("تم إلغاء الوصول إلى كاميرا الويب من قبل المستخدم.");
        } else {
            console.log("حدث خطأ غير متوقع:", error);
        }
    }
}

// استدعاء الدالة للتحقق من الأذونات
checkWebcamPermissions();
```

